async function demoRequest(path,body){await new Promise(resolve=>setTimeout(resolve,180));const url=new URL(path,location.origin);if(url.pathname==='/api/bootstrap')return {ok:true,...clone(demoState)};if(url.pathname==='/api/models')return {ok:true,result:{provider:url.searchParams.get('provider'),models:[{id:'demo-chief',label:'Örnek şef / Demo chief',efforts:['low','medium','high'],origin:'demo'},{id:'demo-helper',label:'Örnek yardımcı / Demo helper',efforts:['low','medium','high'],origin:'demo'}],source:lang==='tr'?'Yalnızca örnek veri':'Demo data only',profiles:['balanced','focused','quality','custom'],roles:Object.keys(roles),max_concurrency:providerCaps[url.searchParams.get('provider')]}};if(url.pathname==='/api/projects/pick')throw Error(t('pickerUnavailable'));if(url.pathname==='/api/projects'){if(body.action==='selection')demoState.selected_projects=body.ids;if(body.action==='add')demoState.projects.push({id:crypto.randomUUID(),name:body.path.split(/[\\/]/).filter(Boolean).pop(),path:body.path});if(body.action==='remove')demoState.projects=demoState.projects.filter(p=>p.id!==body.id);if(body.action==='refresh'&&body.roots)demoState.roots=body.roots;}else if(url.pathname==='/api/orchestras'){if(body.action==='save'){const o=clone(body.orchestra);o.id ||= crypto.randomUUID();demoState.orchestras=demoState.orchestras.filter(existing=>existing.id!==o.id);demoState.orchestras.push(o);}else demoState.orchestras=demoState.orchestras.filter(o=>o.id!==body.id);}else if(url.pathname==='/api/defaults'){if(body.defaults)demoState.defaults=body.defaults;if(body.selected_providers)demoState.selected_providers=body.selected_providers;if(body.project_id)demoState.project_overrides[body.project_id]=body.override;}else if(url.pathname==='/api/preview')return {ok:true,results:body.project_ids.map(id=>({project_id:id,ok:true,preview_id:'demo-preview-'+id,preview:{changes:[{path:'demo/preferences',label:t('selectedOrchestra')+': '+body.payload.name}],demo:true}}))};else if(url.pathname==='/api/apply')return {ok:true,results:body.preview_ids.map(id=>({project_id:id.replace('demo-preview-',''),ok:true,result:{demo:true,changed_files:['demo/preferences']}}))};else if(url.pathname==='/api/restore')return {ok:true,results:body.project_ids.map(id=>({project_id:id,ok:true,result:{demo:true}}))};else if(url.pathname==='/api/usage')return {ok:true,result:{source:lang==='tr'?'Örnek kayıtlar; gerçek kullanım değildir.':'Sample records; not actual usage.',totals:{total_tokens:17200,input_tokens:13000,output_tokens:4200,cached_input_tokens:5000},runs:[{id:'demo-run',name:lang==='tr'?'Ürün sayfası çalışması':'Product page work',total_tokens:17200,input_tokens:13000,output_tokens:4200,cached_input_tokens:5000,actors:[{id:'demo-chief',role:'chief',name:t('chief'),total_tokens:8600,input_tokens:6500,output_tokens:2100},{id:'demo-helper',role:'implementer',name:roleLabel('implementer'),total_tokens:8600,input_tokens:6500,output_tokens:2100}]}]}};else if(url.pathname==='/api/jobs'){if(!body)return {ok:true,jobs:clone(demoState.jobs)};if(body.action==='plan'){const job={id:crypto.randomUUID(),project_id:body.project_ids[0],provider:body.provider,task:body.task,status:'planned',plan:{kind:'proposed_plan',steps:[]},orchestra:body.orchestra,message:t('planLocal')};demoState.jobs.unshift(job);return {ok:true,job:clone(job)};}const job=demoState.jobs.find(j=>j.id===body.id);if(job){job.status=body.action==='cancel'?'cancelled':'needs_attention';job.message=t('demoNote');return {ok:true,job:clone(job)};}}else if(url.pathname.startsWith('/api/jobs/'))return {ok:true,job:clone(demoState.jobs.find(j=>j.id===url.pathname.split('/').pop()))};demoState.revision++;return {ok:true,...clone(demoState)};}
