function normalizeUsage(data){
 const report=clone(data);if(report.status==='unavailable'||report.source==='none')return {...report,totals:{},actors:[],runs:[]};
 if(!report.orchestra?.scopes)return report;
 const records=report.records||[];const actors=(report.orchestra.actors||[]).map(a=>({...a,role:(a.role||'').replaceAll('-','_')}));
 const agents=new Map((report.agents||[]).map(a=>[a.id,a]));
 function rootOf(id){const visited=new Set();while(agents.has(id)&&!visited.has(id)){visited.add(id);const item=agents.get(id);if(item.ambiguous)return '';if(!item.parent)return item.source==='root'?id:'';id=item.parent;}return '';}
 function recordRoot(record){const root=rootOf(record.thread);return root||record.session_id||'';}
 function aggregate(items){const totals={};for(const record of items)for(const [key,value] of Object.entries(record.usage||{}))if(typeof value==='number'&&Number.isFinite(value))totals[key]=(totals[key]??0)+value;return totals;}
 const runs=report.orchestra.scopes.map(scope=>{const observed=records.filter(r=>recordRoot(r)===scope.id);const scopedActors=actors.filter(a=>a.id===scope.id||rootOf(a.id)===scope.id).map(a=>{const chosen=observed.filter(r=>r.thread===a.id);return {...a,...aggregate(chosen),usage_observed:chosen.length>0};});return {...scope,name:scope.name||scope.id,totals:aggregate(observed),actors:scopedActors};});
 return {...report,actors,runs};
}
function rootDialog(first=false){const content=node('div','stack');const text=node('textarea');text.value=state.roots.join('\n');content.append(field(t('optionalRoots'),text),node('p','hint',t('rootsHint')),button(t('browse'),async()=>{const result=await perform('busy',()=>api.request('/api/projects/pick',{}));if(result?.path)text.value=[text.value.trim(),result.path].filter(Boolean).join('\n');}));modal(t('roots'),content,[button(t('cancel'),()=> $('modal').close()),button(t('refresh'),async()=>{const result=await metadata(()=>api.projects({action:'refresh',roots:text.value.split('\n').map(s=>s.trim()).filter(Boolean),revision:state.revision}),'refreshed');if(result){$('modal').close();if(first)finishOnboarding();}},'primary')]);}
